import heapq

def match(orders):
    trades = []
    seq_counter = 0

    # book storage: id -> dict with side, price, qty, seq, active
    book = {}

    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)

    def add_to_book(order_id, side, price, qty, seq):
        book[order_id] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, order_id))
        else:
            heapq.heappush(sell_heap, (price, seq, order_id))

    def top_valid_buy():
        while buy_heap:
            neg_price, seq, oid = buy_heap[0]
            if oid in book and book[oid]['active'] and book[oid]['seq'] == seq:
                return oid
            heapq.heappop(buy_heap)
        return None

    def top_valid_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            if oid in book and book[oid]['active'] and book[oid]['seq'] == seq:
                return oid
            heapq.heappop(sell_heap)
        return None

    def pop_top_buy():
        heapq.heappop(buy_heap)

    def pop_top_sell():
        heapq.heappop(sell_heap)

    for order in orders:
        otype = order[0]

        if otype == 'cancel':
            order_id = order[1]
            if order_id in book and book[order_id]['active']:
                book[order_id]['active'] = False
            continue

        order_id = order[1]
        side = order[2]

        if otype == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            # match against sells
            while remaining > 0:
                sell_id = top_valid_sell()
                if sell_id is None:
                    break
                sell_order = book[sell_id]
                sell_price = sell_order['price']

                if otype == 'market':
                    condition = True
                else:
                    condition = (price >= sell_price)

                if not condition:
                    break

                trade_qty = min(remaining, sell_order['qty'])
                trades.append([order_id, sell_id, sell_price, trade_qty])

                remaining -= trade_qty
                sell_order['qty'] -= trade_qty

                if sell_order['qty'] == 0:
                    sell_order['active'] = False
                    pop_top_sell()
                # if partially filled, stays in place (still valid at top with same seq)
                else:
                    # still has qty, remains in book, don't pop
                    pass

                if sell_order['qty'] == 0:
                    continue
                else:
                    # if incoming remaining is 0, loop will exit naturally
                    if remaining == 0:
                        break
                    else:
                        # incoming still has qty but resting sell also still has qty?
                        # that shouldn't happen since trade_qty = min(...)
                        pass

            if otype == 'limit' and remaining > 0:
                seq_counter += 1
                add_to_book(order_id, 'buy', price, remaining, seq_counter)

        else:  # side == 'sell'
            while remaining > 0:
                buy_id = top_valid_buy()
                if buy_id is None:
                    break
                buy_order = book[buy_id]
                buy_price = buy_order['price']

                if otype == 'market':
                    condition = True
                else:
                    condition = (price <= buy_price)

                if not condition:
                    break

                trade_qty = min(remaining, buy_order['qty'])
                trades.append([buy_id, order_id, buy_price, trade_qty])

                remaining -= trade_qty
                buy_order['qty'] -= trade_qty

                if buy_order['qty'] == 0:
                    buy_order['active'] = False
                    pop_top_buy()
