                    pass

                if buy_order['qty'] == 0:
                    continue
                else:
                    if remaining == 0:
                        break
                    else:
                        pass

            if otype == 'limit' and remaining > 0:
                seq_counter += 1
                add_to_book(order_id, 'sell', price, remaining, seq_counter)

    return trades

